sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    var check = new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().updateCallbackTask(current.sys_id);
    if (check == true) {
        let newCaseTask = null;
        let grTask = new GlideRecordSecure('x_hsb11_mss_unst_0_instructions_case_task');
        grTask.initialize();
        grTask.task_type = 'Update Callback Data';
        grTask.state = 1;
        grTask.instruction_case = current.sys_id;
        grTask.parent = current.sys_id;
        grTask.parent_case = current.sys_id;
        newCaseTask = grTask.insert();
        if (!newCaseTask) {
            gs.info('Business rule - mss_ui_callback_payload - create callback task fail. caseID:' + current.sys_id);
        }
    }
    // This is part of MSSCUSTODY-5541.
    var thrValue, callbackFlag, convertedAmount, inputCurrency, inputAmount, count = 0;

    var data = [];
    var gTask = new GlideRecord('x_hsb11_mss_unst_0_instructions_case_task');
    gTask.addQuery('instruction_case', current.sys_id);
    gTask.addEncodedQuery('outputmessagetype!=MT599');
    gTask.addQuery('task_type', 'Instruction');
    gTask.addActiveQuery();
    gTask.query();
    while (gTask.next()) {
        var requestBody = {};
        var tsh = new GlideRecord('x_hsb11_mss_unst_0_business_region_threshold');
        tsh.addQuery('owning_business', current.owning_business);
        tsh.addQuery('outputmessagetype', gTask.outputmessagetype);
        tsh.query();
        if (tsh.next()) {
            thrValue = Number(tsh.getValue('criteria'));

            callbackFlag = tsh.getValue('callback_flag');

            if (callbackFlag == 1) {
                if (gTask.outputmessagetype == "MT542") {
                    inputCurrency = gTask.currency;
                    inputAmount = gTask.amount;
                    if (inputCurrency != "") {
                        convertedAmount = new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().ConvertToUSD(inputCurrency, inputAmount);
                    } else {
                        convertedAmount = 0;
                    }
                    requestBody.SwbRowId = gTask.getValue('swbrowid');
                    requestBody.Threshold = thrValue;
                    requestBody.UsdAmount = convertedAmount;
                    requestBody.OverThresholdFlag = true;
                    requestBody.CallbackFlag = true;
                } else {
                    if (gTask.outputmessagetype == "MT202" || gTask.outputmessagetype == "MT103" || gTask.outputmessagetype == "MT380") {
                        inputCurrency = gTask.currency;
                        inputAmount = gTask.amount;
                    }
                    convertedAmount = new x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Utils().ConvertToUSD(inputCurrency, inputAmount);


                    if (convertedAmount > thrValue) {

                        requestBody.SwbRowId = gTask.getValue('swbrowid');
                        requestBody.Threshold = thrValue;
                        requestBody.UsdAmount = convertedAmount;
                        requestBody.OverThresholdFlag = true;
                        requestBody.CallbackFlag = true;
                    } else {
                        ++count;
                        requestBody.SwbRowId = gTask.getValue('swbrowid');
                        requestBody.Threshold = thrValue;
                        requestBody.UsdAmount = convertedAmount;
                        requestBody.OverThresholdFlag = false;
                        requestBody.CallbackFlag = true;
                    }
                }
            } else {
                ++count;
                requestBody.SwbRowId = gTask.getValue('swbrowid');
                requestBody.Threshold = 0;
                requestBody.UsdAmount = 0;
                requestBody.OverThresholdFlag = null;
                requestBody.CallbackFlag = false;
            }
        }
        //  if (JSON.stringify(requestBody).length != 2) {

        data.push(requestBody);
        //  } 

    }

    var jsonObj = {};
    jsonObj.Data = data;

    var notRequiredCount = Number(count);

    if (notRequiredCount == data.length) {
        current.setValue('task_status', 'CALLBACK_NOTREQUIRED'); //INSTRUCTIONS_RECEIVED.CALLBACK_NOT_REQUIRED
        // current.setWorkflow(false);
        current.update();
        // current.setWorkflow(true);
    } else {
        current.setValue('task_status', 'CALLBACK_REQUIRED');
        // current.setWorkflow(false);
        current.update();
        // current.setWorkflow(true);
    }


    var record = new GlideRecord("x_hsb11_hsbcmss_sw_hsbc_swb_outbound_table");
    record.initialize();
    record.u_message_id = current.u_message_id;
    record.reference_id = current.sys_id.toString();
    record.payload_version = current.payload_version;
    record.state = 'Ready to be sent';
    record.instruction_type = gTask.instruction_type;
    record.source_system = 'iQube';
    record.owningbusiness = current.owning_business;
    record.process = 'SMARTWORKBENCH_UNSTRUCTURED_INSTRUCTIONS';
    record.swb_id = current.u_objectid.toString();
    record.request_body = JSON.stringify(jsonObj);
    record.process_status = 'UPDATE_CALLBACK_DATA';
    record.insert();


})(current, previous);
